// Probe (night review 2026-11-16, fh): what Find's empty-context search puts in its top 3 for words an engineer
// types in daily work. Read-only; the index is generated by tools/find-index/generate.mjs --out <file>.
//   env -C <review>/app npx tsx <this> <index.json> [query …]
import { readFileSync } from "node:fs";
import { prepare, search } from "../../../app/src/find/rank.ts";
import type { IndexItem } from "../../../app/src/find/types.ts";

const [file, ...given] = process.argv.slice(2);
const items = JSON.parse(readFileSync(file as string, "utf8")) as IndexItem[];
const index = prepare(items);
const DEFAULT = [
  // functions
  "round", "round to 2 decimals", "log base 2", "percent change", "hypotenuse", "quadratic", "polynomial roots",
  "roots", "simultaneous equations", "linear system", "system of equations", "rms", "root mean square",
  "exponential fit", "curve fit", "power fit", "polynomial fit", "logarithmic fit", "regression",
  "radians to degrees", "degrees to radians", "permutations", "npr", "prime factors", "random", "sum", "cumulative sum",
  "numerical integration", "trapezoid", "magnitude", "phase", "polar", "rectangular", "voltage divider", "db",
  "decibel", "sinc", "bessel", "sort", "count", "length", "angle between", "unit vector", "fft", "taylor",
  "partial fractions", "laplace", "weibull", "binomial", "poisson", "chi square", "confidence", "t test",
  "sec", "cot", "nth root", "10^x", "sign", "truncate", "integer part", "nearest integer", "dms", "degrees minutes seconds",
  "rms", "cylindrical", "spherical", "polar to rectangular", "rectangular to polar", "percent error", "log2", "logb",
  "fsolve", "proot", "perm", "polynomial", "zeros", "solve numerically", "newton", "secant",
  // units and constants
  "ksi", "kgf", "kgf/cm2", "torr", "atm", "m3/h", "nm3/h", "scfm", "cfm", "l/s", "btu/h", "ton of refrigeration",
  "kva", "kvar", "var", "mho", "gauss", "lux", "knot", "mach", "centipoise", "cp", "cst", "stokes", "dyne", "kcal",
  "therm", "ps", "metric horsepower", "wh/kg", "kg/m3", "g/cm3", "lb/ft3", "slug", "lbm", "grain", "fl oz",
  "acre", "hectare", "nautical mile", "yard", "micron", "angstrom", "ev", "electron volt", "ppm", "percent",
  "rankine", "water density", "density of water", "speed of sound", "standard atmosphere", "electron mass",
  "earth radius", "g", "gravity", "r", "gas constant", "air density", "mmh2o", "inh2o", "in wc", "psia", "psig",
  "barg", "kj/kg", "s/m", "kg/s", "dbv", "dbu", "w/m2k", "w/mk", "j/kgk", "n/mm2", "mpa", "kn/m", "knm", "nmm", "n mm", "rev/min", "rad/s", "hz",
];
const queries = given.length ? given : DEFAULT;
// A unit slot's Find (app/src/units/menu.ts:81): units and prefixes only, units first. `*` marks tier 0.
const SLOT = { filter: ["unit", "pfx"] as ("unit" | "pfx")[], prefer: ["unit"] as "unit"[] };
const top = (q: string, ctx: object): string =>
  search(index, q, ctx).slice(0, 3).map((h) => `${h.item.id}${h.item.tier ? "" : "*"}`).join("  ") || "(nothing)";
for (const q of queries) console.log(`${JSON.stringify(q).padEnd(26)} math: ${top(q, {})}   |   slot: ${top(q, SLOT)}`);
